// TransactionsNormalizer maps a raw Shopify Transaction JSON to
// entities.TransactionInput. Pulled from the Shopify REST Admin API's
// `/admin/api/<v>/orders/:id/transactions.json` payload format.
type TransactionsNormalizer struct{}

func NewTransactionsNormalizer() *TransactionsNormalizer { return &TransactionsNormalizer{} }

func (n *TransactionsNormalizer) Platform() string { return PlatformID }

// rawShopifyTransaction is the subset of Shopify's Transaction payload
// the canonical mapping needs. Unmapped fields are intentionally
// dropped — adding them later means adding a struct field + touching the
// mapping body, not re-shaping the canonical aggregate.
type rawShopifyTransaction struct {
	ID          int64  `json:"id"`
	OrderID     int64  `json:"order_id"`
	Kind        string `json:"kind"`
	Status      string `json:"status"`
	Amount      string `json:"amount"`
	Currency    string `json:"currency"`
	Gateway     string `json:"gateway"`
	ProcessedAt string `json:"processed_at"`
}

// Normalize parses + maps the raw payload to a entities.TransactionInput.
// Errors wrap ErrNormalizerBadPayload so the pipeline can skip + continue.
func (n *TransactionsNormalizer) Normalize(raw []byte, in pipelines.RunInput) (entities.TransactionInput, error) {
	var rt rawShopifyTransaction
	if err := json.Unmarshal(raw, &rt); err != nil {
		return entities.TransactionInput{}, fmt.Errorf("%w: %v", ErrNormalizerBadPayload, err)
	}
	if rt.ID == 0 {
		return entities.TransactionInput{}, fmt.Errorf("%w: missing id", ErrNormalizerBadPayload)
	}

	amountCents, err := parseDecimalToCents(rt.Amount)
	if err != nil {
		return entities.TransactionInput{}, fmt.Errorf("%w: amount: %v", ErrNormalizerBadPayload, err)
	}

	amountMA, err := objects.NewMonetaryAmount(amountCents, rt.Currency)
	if err != nil {
		return entities.TransactionInput{}, fmt.Errorf("%w: currency: %v", ErrNormalizerBadPayload, err)
	}

	var processedAt time.Time
	if rt.ProcessedAt != "" {
		processedAt, err = parseShopifyTime(rt.ProcessedAt)
		if err != nil {
			return entities.TransactionInput{}, fmt.Errorf("%w: processed_at: %v", ErrNormalizerBadPayload, err)
		}
	}

	orderExternalID := ""
	if rt.OrderID != 0 {
		orderExternalID = strconv.FormatInt(rt.OrderID, 10)
	}

	return entities.TransactionInput{
		Platform:                   PlatformID,
		ExternalID:                 strconv.FormatInt(rt.ID, 10),
		StoreID:                    in.StoreID,
		StoreIntegrationID:         in.StoreIntegrationID,
		StoreIntegrationExternalID: in.StoreIntegrationExternalID,
		OrderExternalID:            orderExternalID,
		Kind:                       mapTransactionKind(rt.Kind),
		Status:                     mapTransactionStatus(rt.Status),
		Amount:                     amountMA,
		Gateway:                    mapGateway(rt.Gateway),
		ProcessedAt:                processedAt,
	}, nil
}

// mapTransactionKind maps a raw Shopify transaction kind string to the
// canonical wire.TransactionKind value. Shopify uses lowercase; the wire
// catalog uses uppercase.
func mapTransactionKind(s string) string {
	switch strings.ToUpper(s) {
	case string(wire.TransactionKindAUTHORIZATION):
		return string(wire.TransactionKindAUTHORIZATION)
	case "CAPTURE", "SALE":
		return string(wire.TransactionKindCHARGE)
	case string(wire.TransactionKindREFUND):
		return string(wire.TransactionKindREFUND)
	case string(wire.TransactionKindVOID):
		return string(wire.TransactionKindVOID)
	default:
		return strings.ToUpper(s)
	}
}

// mapTransactionStatus maps a raw Shopify transaction status string to the
// canonical wire.TransactionStatus value.
func mapTransactionStatus(s string) string {
	switch strings.ToUpper(s) {
	case string(wire.TransactionStatusPENDING):
		return string(wire.TransactionStatusPENDING)
	case string(wire.TransactionStatusSUCCESS):
		return string(wire.TransactionStatusSUCCESS)
	case string(wire.TransactionStatusFAILURE):
		return string(wire.TransactionStatusFAILURE)
	case string(wire.TransactionStatusERROR):
		return string(wire.TransactionStatusERROR)
	default:
		return strings.ToUpper(s)
	}
}

// TransactionNormalizer is the interface a ShopifyTransactionsPipeline expects.
type TransactionNormalizer interface {
	Platform() string
	Normalize(raw []byte, in pipelines.RunInput) (entities.TransactionInput, error)
}

// compile-time interface check
var _ TransactionNormalizer = (*TransactionsNormalizer)(nil)

