// MonetaryAmount pairs cents with the ISO-4217 currency the cents
// are denominated in. The aggregate's invariant: every money field
// MUST be constructed through `NewMonetaryAmount` so we know the
// currency is recognised + the amount is a valid int64.
type MonetaryAmount struct {
	amountCents int64
	currency    wire.CurrencyCode
}

var ErrMonetaryInvalidCurrency = errors.New("monetary: invalid currency")

// NewMonetaryAmount validates the currency string against the wire
// enum catalog. The cents are accepted as-is (negative is legal:
// refunds, allocated discounts, fee adjustments).
func NewMonetaryAmount(amountCents int64, currency string) (MonetaryAmount, error) {
	cur, err := wire.ParseCurrencyCode(currency)
	if err != nil {
		return MonetaryAmount{}, fmt.Errorf("%w: %v", ErrMonetaryInvalidCurrency, err)
	}
	return MonetaryAmount{amountCents: amountCents, currency: cur}, nil
}

// MustMonetaryAmount panics on invalid currency. Reserved for tests
// and fixture builders — pipelines + normalizers MUST go through
// NewMonetaryAmount so provider-side bad data surfaces as an error
// up the call chain.
func MustMonetaryAmount(amountCents int64, currency wire.CurrencyCode) MonetaryAmount {
	return MonetaryAmount{amountCents: amountCents, currency: currency}
}

// IsZero reports whether the value is the zero MonetaryAmount (used
// to disambiguate "not present" from "present but zero"; optional
// money fields on the aggregate use `*MonetaryAmount` not this).
func (m MonetaryAmount) IsZero() bool {
	return m.amountCents == 0 && m.currency == ""
}

