func (m MonetaryAmount) Currency() wire.CurrencyCode { return m.currency }

// CurrencyMinorUnits returns the ISO-4217 number of fractional digits
// (the minor-unit exponent) for a currency. Provider amounts arrive as
// decimal strings in the order's currency; to store them as integer
// minor units we must scale by 10^exponent — which is 2 for most
// currencies, 0 for zero-decimal ones (JPY, KRW, CLP…) and 3 for the
// Gulf/dinar group (KWD, BHD, OMR…). Hardcoding ×100 silently corrupts
// both groups. Unknown/unparseable codes fall back to 2; the bad
// currency surfaces later through NewMonetaryAmount.
func CurrencyMinorUnits(currency string) int {
	cur, err := wire.ParseCurrencyCode(currency)
	if err != nil {
		return 2
	}
	switch cur {
	// Zero-decimal currencies — the amount has no fractional part.
	case wire.CurrencyCodeBIF, wire.CurrencyCodeCLP, wire.CurrencyCodeGNF,
		wire.CurrencyCodeISK, wire.CurrencyCodeJPY, wire.CurrencyCodeKRW,
		wire.CurrencyCodePYG, wire.CurrencyCodeRWF, wire.CurrencyCodeUGX,
		wire.CurrencyCodeVND, wire.CurrencyCodeXAF, wire.CurrencyCodeXOF:
		return 0
	// Three-decimal currencies — the amount has three fractional digits.
	case wire.CurrencyCodeBHD, wire.CurrencyCodeJOD, wire.CurrencyCodeKWD,
		wire.CurrencyCodeOMR, wire.CurrencyCodeTND:
		return 3
	default:
		return 2
	}
}

