func joinPointer(a *string, sep string, b *string) string {
	first := ""
	if a != nil {
		first = *a
	}
	second := ""
	if b != nil {
		second = *b
	}
	if first == "" {
		return second
	}
	if second == "" {
		return first
	}
	return first + sep + second
}

