func TestParseDecimalToCents(t *testing.T) {
	tests := []struct {
		in   string
		want int64
	}{
		{"100", 10000},
		{"100.00", 10000},
		{"100.5", 10050},
		{"100.50", 10050},
		{"100.55", 10055},
		{"0", 0},
		{"0.00", 0},
		{"-12.34", -1234},
		{"", 0},
	}
	for _, tt := range tests {
		got, err := parseDecimalToCents(tt.in)
		if err != nil {
			t.Errorf("parseDecimalToCents(%q) err = %v", tt.in, err)
		}
		if got != tt.want {
			t.Errorf("parseDecimalToCents(%q) = %d, want %d", tt.in, got, tt.want)
		}
	}
}

