func TestParseDecimalToMinorUnits(t *testing.T) {
	tests := []struct {
		in       string
		exponent int
		want     int64
	}{
		// 2-decimal currencies (USD, BRL, EUR…)
		{"100", 2, 10000},
		{"100.00", 2, 10000},
		{"100.5", 2, 10050},
		{"100.50", 2, 10050},
		{"100.55", 2, 10055},
		{"100.567", 2, 10056}, // excess fractional digits truncated
		{"0", 2, 0},
		{"0.00", 2, 0},
		{"-12.34", 2, -1234},
		{"", 2, 0},
		// 0-decimal currencies (JPY, KRW, CLP…): no minor unit
		{"1000", 0, 1000},
		{"1000.0", 0, 1000}, // any fractional part is ignored
		{"-500", 0, -500},
		// 3-decimal currencies (KWD, BHD, OMR…)
		{"1.234", 3, 1234},
		{"1.2", 3, 1200}, // missing digits right-padded
		{"1", 3, 1000},
		{"-0.500", 3, -500},
	}
	for _, tt := range tests {
		got, err := parseDecimalToMinorUnits(tt.in, tt.exponent)
		if err != nil {
			t.Errorf("parseDecimalToMinorUnits(%q, %d) err = %v", tt.in, tt.exponent, err)
		}
		if got != tt.want {
			t.Errorf("parseDecimalToMinorUnits(%q, %d) = %d, want %d", tt.in, tt.exponent, got, tt.want)
		}
	}
}

