func TestMapFinancialStatus(t *testing.T) {
	tests := map[string]string{
		"paid":               string(wire.PaymentStatusPAID),
		"partially_paid":     string(wire.PaymentStatusPARTIALLY_PAID),
		"refunded":           string(wire.PaymentStatusREFUNDED),
		"partially_refunded": string(wire.PaymentStatusPARTIALLY_REFUNDED),
		"voided":             string(wire.PaymentStatusVOIDED),
		"pending":            string(wire.PaymentStatusPENDING),
		"authorized":         string(wire.PaymentStatusAUTHORIZED),
		"unpaid":             string(wire.PaymentStatusUNPAID),
		"":                   string(wire.PaymentStatusPENDING), // unknown defaults to PENDING
	}
	for in, want := range tests {
		if got := mapFinancialStatus(in); got != want {
			t.Errorf("mapFinancialStatus(%q) = %q, want %q", in, got, want)
		}
	}
}
